+func TestInstanceMetadataClientIsAvailable(t *testing.T) {
+	tests := []struct {
+		name string
+		id   string
+		want bool
+	}{
+		{name: "short instance ID", id: "i-1a2b3c4d", want: true},
+		{name: "long instance ID", id: "i-1234567890abcdef0", want: true},
+		{name: "captive portal HTML", id: "<!DOCTYPE html><html>Login</html>"},
+		{name: "invalid length", id: "i-123456789"},
+		{name: "invalid characters", id: "i-1234567g"},
+		{name: "extra content", id: "i-1a2b3c4d\n<html>Login</html>"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
