+					t.Errorf("unexpected IMDS request: %s %s", r.Method, r.URL.Path)
+					w.WriteHeader(http.StatusBadRequest)
+					return
+				}
+				_, _ = w.Write([]byte(tt.id))
+			}))
+			defer server.Close()
+
+			client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{Endpoint: server.URL})))
+			require.NoError(t, err)
+			assert.Equal(t, tt.want, client.IsAvailable(context.Background()))
+		})
+	}
+}
+
+func TestInstanceMetadataClientIsAvailableTimeout(t *testing.T) {
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.Method == http.MethodPut {
+			w.WriteHeader(http.StatusNotFound)
+			return
+		}
+		<-r.Context().Done()
+	}))
+	defer server.Close()
+
+	client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{Endpoint: server.URL})))
+	require.NoError(t, err)
+	start := time.Now()
+	assert.False(t, client.IsAvailable(context.Background()))
+	assert.Less(t, time.Since(start), time.Second)
+}
+
+func TestNewInstanceMetadataClientOptions(t *testing.T) {
+	wantErr := errors.New("option failed")
